head.script:
/**
 * @component
 * @componentName udc_searchBadge
 * @pluginName 
 * @company Inswave
 * @developer Inswave
 * @category /cm/udc
 * @notSupportBrowser 
 * @version
 * @htmlRender
 * @icon
 * @disableIcon
 * @description  검색 항목의 직관적인 시각화를 통해 검색 항목을 식별하는 UDC 컴포넌트
 * @width 150px
 * @height 30px
 * @license
 * @imagePath
 * @homepage
 */

/**
 * @property
 * @name id
 * @category 01.Basic & ETC
 * @type string
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트의 ID 를 설정합니다.
 */

/**
 * @property
 * @name class
 * @category 01.Basic & ETC
 * @type string
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트에 적용하려는 클래스의 이름을 설정합니다.
 */

/**
 * @property
 * @name style
 * @category 01.Basic & ETC
 * @type string
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트에 적용하려는 style을 설정합니다.
 */

/**
 * @property
 * @name separator
 * @category 02.Tooltip & Format & Multi-lang
 * @type string
 * @option
 * @default ,
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트에서 두 개 이상의 아이템을 선택했을때 Value 값을 구분하는 구분자를 설정합니다.
 */

/**
 * @property
 * @name bindColumn
 * @category 03.Data
 * @type combobox
 * @option [value,label]
 * @default label
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 데이터 선택 기본 키 값을 설정합니다.
 */

/**
 * @property
 * @name ref
 * @category 03.Data
 * @type bindColumn
 * @option
 * @default
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 컴포넌트의 입력값에 바인딩할 DataCollection 정보를 설정합니다.
 */

/**
 * @property
 * @name dataList
 * @category 03.Data
 * @type bindDataList
 * @option
 * @default
 * @necessary Y
 * @bindparent
 * @migrationStatus
 * @description 데이터에 해당하는 데이터컬렉션의 DataList의 아이디
 */

/**
 * @property
 * @name disabled
 * @category 01.Basic & ETC
 * @type combobox
 * @option [true,false]
 * @default false
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 비활성화(disabled) 상태를 true/false 로 설정합니다.
 * • true : 비활성화(disabled) 상태로 설정 (접근 불가)
 * • false : 비활성화(disabled) 상태를 해제 (접근 가능)
 */

/**
 * @property
 * @name readOnly
 * @category 01.Basic & ETC
 * @type combobox
 * @option [true,false]
 * @default false
 * @necessary N
 * @bindparent
 * @migrationStatus
 * @description 읽기 전용(readonly) 상태를 true/false 로 설정합니다.
 * • true : 읽기 전용(readonly) 상태를 설정 (편집 불가)
 * • false : 읽기 전용(readonly) 상태를 해제 (편집 가능)
 */

// ═══════════════════════════════════════════════════════════════
// 라이프사이클
// ═══════════════════════════════════════════════════════════════

scwin.options = {};

// dataList 전역 변수
scwin.dataList = null;

/**
 * @event 
 * @name onwframeload
 * @description 화면이 열리기 전 발생하는 이벤트. UDC 초기화에 필요한 코드를 작성한다.
 */
scwin.onwframeload = function () {
	const defaultOptions = {
		disabled : false,
		readOnly : false,
		ref : "",
		bindColumn : "label",
		separator : ",",
		dataList : ""
	};

	scwin.options = $p.getOptions(defaultOptions);

	scwin.options.disabled = (scwin.options.disabled.toString().trim().toLowerCase() === "true");
	scwin.options.readOnly = (scwin.options.readOnly.toString().trim().toLowerCase() === "true");	

	if (!$c.util.isEmpty(scwin.options.dataList)) {
		scwin.dataList = scwin.__getDataCollection(scwin.options.dataList);
	} else {
		scwin.dataList = dltSearchBadge;
	}
};

/**
 * @event 
 * @name onpageload
 * @description 화면이 열렸을 때 엔진 초기화 작업이 끝난 뒤에 발생하는 이벤트. 화면 초기화에 필요한 코드를 작성한다.
 */
scwin.onpageload = function () {
	// UDC 컴포넌트 초기 속성 설정
	scwin.__initComponent();
};

/**
 * @method
 * @name __initComponent
 * @description UDC 컴포넌트 초기 속성 설정 (내부용)
 * @param
 * @returns
 * @hidden Y
 * @exception
 * @migrationStatus
 * @example // UDC 컴포넌트 초기 속성 설정
 * scwin.__initComponent();
 */
scwin.__initComponent = function() {
	genSearchBadge.setDisabled(scwin.options.disabled);
	genSearchBadge.setReadOnly(scwin.options.readOnly);

	if (!$c.util.isEmpty(scwin.options.ref)) {
		iptRef.setRef(scwin.getDataBindInfo(scwin.options.ref));
	}

	// UDC 컴포넌트의 Badge 생성 함수
	scwin.__generateSearchBadge();
};

/**
 * @method
 * @name __generateSearchBadge
 * @description UDC 컴포넌트의 Badge 생성 함수 (내부용)
 * @param
 * @returns
 * @hidden Y
 * @exception
 * @migrationStatus
 * @example
 * // UDC 컴포넌트의 Badge 생성 함수
 * scwin.__generateSearchBadge();
 */
scwin.__generateSearchBadge = function() {
	genSearchBadge.removeAll();

	scwin.dataList.getAllJSON().forEach((row, i) => {
		genSearchBadge.insertChild(i);

		const tmpBadge = genSearchBadge.getChild(i, "btnBadge");
		const tmpLabel = genSearchBadge.getChild(i, "lblLabel");

		tmpBadge.setUserData("index", i);
		tmpLabel.setValue(row.label ?? "");
	});

	// ref 바인딩 값은 bindColumn 옵션 컬럼을 separator 로 연결한 문자열
	iptRef.setValue(scwin.__getValuesByKey(scwin.options.bindColumn).join(scwin.options.separator));
};

/**
 * @method
 * @name __getValuesByKey
 * @description UDC 컴포넌트의 dataList에서 특정 key의 값을 배열로 리턴하는 함수 (내부용)
 * @param {string} key 조회할 컬럼(key) id
 * @returns {array} 각 Row 의 key 컬럼 값 배열
 * @hidden Y
 * @exception
 * @migrationStatus
 * @example
 * // 전체 Row 의 label 값 배열 조회
 * const labelArr = scwin.__getValuesByKey("label");
 */
scwin.__getValuesByKey = function(key) {
	return scwin.dataList.getAllJSON().map(item => item[key]);
};

/**
 * @method
 * @name getValue
 * @description 배지 아이템들의 value 값을 구분자로 구분한 문자열로 반환합니다.
 * @param {string} delimiter 아이템들의 value 값을 구분하는 구분자를 텍스트로 설정합니다.
 * 파라미터를 설정하지 않거나 ""(Empty String)으로 설정 시 separator 속성값(기본 ",")이 적용됩니다.
 * @returns {string} result 아이템들의 value 값을 구분자가 포함된 문자열로 반환합니다.
 * 아이템이 한 개인 경우 구분자 없이 해당 아이템의 value 값만 반환하고,
 * 아이템이 없는 경우 ""(Empty String)을 반환합니다.
 * @hidden N
 * @exception
 * @migrationStatus
 * @example  // "," 문자를 구분자로 아이템들의 value 값 조회 ("0,2,3" 형식으로 반환)
 * searchBadge1.getValue(",");
 */
scwin.getValue = function (delimiter) {
	const sep = $c.util.isEmpty(delimiter) ? scwin.options.separator : delimiter;
	return scwin.__getValuesByKey("value").join(sep);
};

/**
 * @method
 * @name getText
 * @description 배지 아이템들의 라벨(label)값을 구분자로 구분한 문자열로 반환합니다.
 * @param {string} delimiter 아이템들의 라벨값을 구분하는 구분자를 텍스트로 설정합니다.
 * 파라미터를 설정하지 않거나 ""(Empty String)으로 설정 시 separator 속성값(기본 ",")이 적용됩니다.
 * @returns {string} result 아이템들의 라벨값을 구분자가 포함된 문자열로 반환합니다.
 * 아이템이 한 개인 경우 구분자 없이 해당 아이템의 라벨값만 반환하고,
 * 아이템이 없는 경우 ""(Empty String)을 반환합니다.
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // "," 문자를 구분자로 아이템들의 라벨값 조회 ("발행사,종목명" 형식으로 반환)
 * searchBadge1.getText(",");
 */
scwin.getText = function (delimiter) {
	const sep = $c.util.isEmpty(delimiter) ? scwin.options.separator : delimiter;
	return scwin.__getValuesByKey("label").join(sep);
};

/**
 * @method
 * @name getAllJSON
 * @description 	필터/정렬이 적용되지 않은 상태를 기준으로 DataList 모듈의 전체 Row 데이터를 JSON 객체의 배열로 반환합니다.
 * @param
 * @returns {object} scwin.dataList의 JSON 데이터 리턴
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // searchBadge에 적용된 DataList의 전체 Row 데이터를 JSON 객체의 배열로 반환
 * searchBadge1.getAllJSON();
 */
scwin.getAllJSON = function () {
	return scwin.dataList.getAllJSON();
};

/**
 * @method
 * @name setJSON
 * @description JSON 객체의 배열을 사용하여 DataList 모듈의 데이터를 새로 설정하거나 추가합니다.
 * @param {array} jsonData 새로 설정하거나 추가할 데이터를 JSON 객체의 배열로 설정합니다.
 * @param {boolean} append jsonData 파라미터의 데이터를 기존 데이터에 추가할지 true/false 로 설정합니다.
 * • true : 기존 데이터에 jsonData 파라미터의 데이터를 마지막 위치에 추가합니다.
 * • false : 기존 데이터를 모두 삭제하고 jsonData 파라미터의 데이터로 새로 설정합니다.
 * (빈 배열 [] 을 append=false 로 전달하면 전체 데이터가 삭제됩니다.)
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 2개 Column 으로 정의된 DataList 의 데이터 생성
 * const jsonData = [
 * 	{ key : "001", value : "홍길동" },
 * 	{ key : "002", value : "김철수" },
 * 	{ key : "005", value : "이영희" },
 * 	...
 * ];
 *  
 * // DataList 에 데이터 추가
 * searchBadge1.setJSON(jsonData, false);
 */
scwin.setJSON = function (jsonData, append = false) {
	// 빈 배열 + 전체 교체(append=false)는 "전체 비우기"로 허용, null/undefined 는 무시
	if (!$c.util.isEmpty(jsonData) || (Array.isArray(jsonData) && !append)) {
		scwin.dataList.setJSON(jsonData, append);

		// UDC 컴포넌트의 Badge 생성 함수
		scwin.__generateSearchBadge();
	}
};

/**
 * @method
 * @name setRowJSON
 * @description 지정한 Row 인덱스 위치에 JSON 객체로 Row 데이터를 한 건 삽입하거나 덮어쓰기 합니다.
 * @param {number} rowIndex Row 데이터가 삽입 또는 덮어쓰기 될 위치의 인덱스값을 숫자로 설정합니다.
 * Row 의 인덱스는 0 부터 시작하며 필터/정렬 설정에 맞게 인덱스를 설정합니다.
 * @param {object} rowData 삽입 또는 덮어쓰기 하려는 Row 데이터를 JSON 객체로 설정합니다.
 * DataList 모듈의 Column ID 를 Key 로 "Column ID:Value" 형태의 Key-Value 쌍으로 구성합니다.
 * Key-Value 쌍으로 설정하지 않은 Column 엔 값이 설정되지 않습니다.
 * @param {boolean} overwrite rowData 파라미터의 Row 데이터를 덮어쓰기 할지 true/false 로 설정합니다.
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example 
 * const rowData = { key : "001", value : "홍길동" };
 *  
 * // DataList의 Row 인덱스 위치에 데이터 추가
 * searchBadge1.setRowJSON(0, rowData, false);
 */
scwin.setRowJSON = function (rowIndex, rowData, overwrite = false) {
	if (!$c.util.isEmpty(rowData)) {
		scwin.dataList.setRowJSON(rowIndex, rowData, overwrite);

		// UDC 컴포넌트의 Badge 생성 함수
		scwin.__generateSearchBadge();
	}
};

/**
 * @method
 * @name getRowCount
 * @description DataList 모듈의 전체 Row 데이터의 Count를 반환합니다.
 * @param
 * @returns {number} scwin.dataList의 Row Count 리턴
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // searchBadge에 적용된 DataList의 전체 Row 데이터의 Count를 반환
 * const rowCount = searchBadge1.getRowCount();
 */
scwin.getRowCount = function () {
	return scwin.dataList.getRowCount();
};

/**
 * @method
 * @name getDisabled
 * @description 컴포넌트에 적용된 비활성화(disabled) 상태값을 반환합니다.
 * @param 
 * @returns {boolean} result 비활성화(disabled) 상태를 true/false 로 반환합니다.
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 컴포넌트의 disabled 상태값을 반환
 * searchBadge1.getDisabled();
 */
scwin.getDisabled = function () {
	return genSearchBadge.getDisabled();
};

/**
 * @method
 * @name getReadOnly
 * @description 컴포넌트에 적용된 읽기 전용(readonly) 상태값을 반환합니다.
 * @param
 * @returns {boolean} result 읽기 전용(readonly) 상태를 true/false 로 반환합니다.
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 컴포넌트의 readonly 상태값을 반환
 * searchBadge1.getReadOnly();
 */
scwin.getReadOnly = function () {
	return genSearchBadge.getReadOnly();
};

/**
 * @method
 * @name setDisabled
 * @description 컴포넌트의 비활성화(disabled) 상태를 설정합니다.
 * @param {boolean} disabled 비활성화(disabled) 상태를 true/false 로 설정합니다.
 * • true : 비활성화(disabled) 상태로 설정 (접근 불가)
 * • false : 비활성화(disabled) 상태를 해제 (접근 가능)
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 컴포넌트의 disabled 상태값을 설정
 * searchBadge1.setDisabled(true);
 */
scwin.setDisabled = function (disabled) {
	genSearchBadge.setDisabled(disabled);
};

/**
 * @method
 * @name setReadOnly
 * @description 컴포넌트의 읽기 전용(readonly) 상태를 설정합니다.
 * @param {boolean} readOnly 읽기 전용(readonly) 상태를 true/false 로 설정합니다.
 * • true : 읽기 전용(readonly) 상태를 설정 (편집 불가)
 * • false : 읽기 전용(readonly) 상태를 해제 (편집 가능)
 * @returns
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 컴포넌트의 readonly 상태값을 설정
 * searchBadge1.setReadOnly(true);
 */
scwin.setReadOnly = function (readOnly) {
	genSearchBadge.setReadOnly(readOnly);
};

/**
 * @method
 * @name getDataBindInfo
 * @description 바인딩한 DataMap 의 key 혹은 DataList의 Column 정보를 매핑해주는 함수 
 * @param {string} ref 바인드 데이터 String(data:dmMap1.endDate)
 * @returns {string} 바인딩 된 Data 문자열 리턴
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 부모 화면 DataMap 바인딩 문자열의 컬렉션 id 를 런타임 전체 id 로 치환
 * iptRef.setRef(scwin.getDataBindInfo("data:dmSearch.isurNm"));
 */
scwin.getDataBindInfo = function (ref) {
	let returnData = "";

	try {
		if (typeof ref === "string" && ref.startsWith("data:")) {
			const dataMapId = scwin.__getDataCollection(ref).getID();
			returnData = ref.replace(/:([^.]+)/, `:${dataMapId}`);
		}
	} catch(e) {
		console.error("getDataBindInfo 함수 오류 발생", e);
	} finally {
		return returnData;
	}
};

/**
 * @method
 * @name getDataCollectionInfo
 * @description 바인딩한 DataCollection의 객체를 리턴하고, 컴포넌트 내부 dataList 참조를 해당 객체로 교체하는 함수
 * @param {string} dataList 바인드 데이터 String(data:dltSearch)
 * @returns {object} DataCollection 객체 (조회 실패 시 null)
 * @hidden N
 * @exception
 * @migrationStatus
 * @example // 부모 화면의 dltSearch 로 데이터 소스를 교체
 * searchBadge1.getDataCollectionInfo("data:dltSearch");
 */
scwin.getDataCollectionInfo = function(dataList) {
	let returnCollection = null;

	try {
		returnCollection = scwin.__getDataCollection(dataList);
		scwin.dataList = returnCollection;
	} catch(e) {
		console.error("getDataCollectionInfo 함수 오류 발생", e);
	} finally {
		return returnCollection;
	}
};

/**
 * @method
 * @name __getDataCollection
 * @description 문자열에 포함된 DataCollection의 객체를 부모 화면에서 찾아 리턴해주는 함수 (내부용)
 * @param {string} dataString 바인드 데이터 String(data:dltSearch)
 * @returns {object} DataCollection 객체 ("data:" 형식이 아니면 null)
 * @hidden Y
 * @exception
 * @migrationStatus
 * @example
 * scwin.dataList = scwin.__getDataCollection(scwin.options.ref);
 * scwin.dataList = scwin.__getDataCollection(scwin.options.dataList);
 */
scwin.__getDataCollection = function(dataString) {
	if (typeof dataString === "string" && dataString.startsWith("data:")) {
		const arr = dataString.slice(5).split(".");

		return $p.parent().$p.getComponentById(arr[0]);
	} else {
		return null;
	}
};

/**
 * @event
 * @name emit_onclick
 * @author inswave
 * @date 2026. 08. 03
 * @description Badge 삭제 버튼 click 이벤트
 * @param {object} e event 객체
 * @returns
 * @hidden N
*/
scwin.emit_onclick = function (e) {
	$p.emit("btnBadge_onclick", e);

	const btnObj = $p.getComponentById(e.target?.id);

	// 클릭 대상이 배지 버튼 자신인 경우에만 삭제 (내부 라벨 textbox 클릭은 무시)
	if (this === btnObj) {
		const index = Number.parseInt(btnObj.getUserData("index") || 0, 10);
		scwin.dataList.removeRow(index);

		// UDC 컴포넌트의 Badge 생성 함수
		scwin.__generateSearchBadge();
	}
};

/**
 * @event
 * @name onViewChange
 * @description 키보드 또는 마우스 조작을 통해 값이 변경된 경우 발생
 * 스크립트를 통해 값이 변경된 경우에는 발생하지 않음.
 * @param {object} info info.oldValue, info.newValue를 포함한 JSON을 반환한다.
 * @migrationStatus
 * @example
 */
scwin.emit_onViewChange = function (info) {
	$p.emit("onViewChange", info);
};
